/**
 * Questions loader — fetches pre-generated JSON problem files from public/questions/.
 *
 * Problem files are generated by AI (Claude Code / Claude agent) and saved as JSON.
 * The frontend only reads these files; no network/API calls to AI are made at runtime.
 *
 * Directory structure (under public/questions/):
 *   toefl/reading/complete-words/      *.json
 *   toefl/reading/daily-life/          *.json
 *   toefl/reading/academic/            *.json
 *   toefl/writing/build-sentence/      *.json
 *   toefl/writing/email/               *.json
 *   toefl/writing/discussion/          *.json
 *   toefl/speaking/listen-repeat/      *.json
 *   toefl/speaking/interview/          *.json
 *   toeic/part5/                       *.json
 *   toeic/part6/                       *.json
 *   toeic/part7/                       *.json
 *
 * Each directory has an index.json listing available files, generated by
 * vite.config.ts; don't edit it by hand.
 *
 * Never rename a question file or reuse a deleted name: the basename is the
 * ID that saved attempts point at.
 */

export interface QuestionIndex {
  files: string[];
}

export interface LoadedQuestion<T> {
  data: T;
  file: string;
}

export interface QuestionFileEntry {
  file: string;
  id: string;
}

const QUESTION_ID = /^[a-z0-9-]+$/i;

// A missing file is not a 404 here: the dev server and Pages both answer with
// the SPA's index.html and a 200, so `ok` alone can't catch it.
async function readJson<T>(res: Response, missing: string): Promise<T> {
  if (!res.ok) throw new Error(missing);
  try {
    return (await res.json()) as T;
  } catch {
    throw new Error(missing);
  }
}

export function questionIdFromFile(file: string): string {
  return file.replace(/\.json$/i, "");
}

/**
 * The topic a slugged ID names (`20261007-roman-roads` → "Roman roads"), or
 * null for numbered IDs, which only have their position to go by.
 */
export function questionTopic(id: string): string | null {
  const slug = id.replace(/^\d{8}-/, "");
  if (slug === id || /^\d+$/.test(slug)) return null;
  const words = slug.replace(/-/g, " ");
  return words.charAt(0).toUpperCase() + words.slice(1);
}

export async function fetchQuestionIndex(
  taskPath: string,
): Promise<QuestionIndex> {
  const res = await fetch(`/questions/${taskPath}/index.json`);
  return readJson(
    res,
    `No questions yet. Add JSON files under public/questions/${taskPath}/.`,
  );
}

export async function fetchRandomQuestion<T>(taskPath: string): Promise<T> {
  const loaded = await fetchRandomQuestionWithMeta<T>(taskPath);
  return loaded.data;
}

export async function listQuestionFiles(
  taskPath: string,
): Promise<QuestionFileEntry[]> {
  const index = await fetchQuestionIndex(taskPath);
  // Plain code-unit order, so `>` on IDs agrees with list order.
  return index.files
    .map((file) => ({ file, id: questionIdFromFile(file) }))
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

export async function fetchQuestionByFileWithMeta<T>(
  taskPath: string,
  file: string,
): Promise<LoadedQuestion<T>> {
  const res = await fetch(`/questions/${taskPath}/${file}`);
  const data = await readJson<T>(
    res,
    `Question ${questionIdFromFile(file)} doesn't exist. Pick another from the list.`,
  );
  return { data, file };
}

export async function fetchQuestionByIdWithMeta<T>(
  taskPath: string,
  id: string,
): Promise<LoadedQuestion<T>> {
  if (!QUESTION_ID.test(id)) {
    throw new Error(`Invalid question ID "${id}".`);
  }
  return fetchQuestionByFileWithMeta<T>(taskPath, `${id}.json`);
}

export async function fetchRandomQuestionWithMeta<T>(
  taskPath: string,
): Promise<LoadedQuestion<T>> {
  const files = await listQuestionFiles(taskPath);
  if (files.length === 0) {
    throw new Error(
      `No questions yet. Add JSON files under public/questions/${taskPath}/.`,
    );
  }
  const selected = files[Math.floor(Math.random() * files.length)];
  return fetchQuestionByFileWithMeta<T>(taskPath, selected.file);
}

export async function fetchAllQuestions<T>(taskPath: string): Promise<T[]> {
  const index = await fetchQuestionIndex(taskPath);
  const results = await Promise.all(
    index.files.map(async (file) => {
      const res = await fetch(`/questions/${taskPath}/${file}`);
      return readJson<T>(res, `Failed to load: ${file}`);
    }),
  );
  return results;
}
